    g.clearRect(0, 0, 9, 5);
    P(f ? 'rgba(141,134,168,.5)' : 'rgba(201,195,224,.9)', 0, 0, 3); P(f ? 'rgba(201,195,224,.9)' : 'rgba(141,134,168,.5)', 6, 0, 3);   // the rotors, a blur
    P('#2a2540', 1, 1); P('#2a2540', 7, 1); P('#1d1930', 1, 2, 7); P('#1d1930', 3, 3, 3); P('#3a2a40', 4, 3);   // masts, body, the LED's socket
    P('#2a2540', 2, 4); P('#2a2540', 6, 4);                                                                   // legs
